-- Add Perceiver Resampler method, introduced in arXiv 2204.14198. The source paper
-- gets the source evidence row (Introduced banner); citers are linked by
-- link_papers_by_source_citations.py and the hourly reference backfill.

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'perceiver-resampler',
    'Perceiver Resampler',
    'Perceiver Resampler',
    'The Perceiver Resampler is the vision-language connector introduced in Flamingo. It takes a variable number of visual features from a frozen vision encoder, from a single image or many video frames with added temporal embeddings, and maps them to a fixed, small number of visual tokens (64 in Flamingo). A set of learned latent queries cross-attends to the visual features, together with the latents themselves, followed by feed-forward layers, in the style of the Perceiver architecture. The resulting tokens condition a frozen language model through interleaved gated cross-attention layers, which keeps the cost of attending to images independent of their resolution or number of frames. Flamingo used it to set few-shot state of the art across 16 image and video understanding benchmarks. Learned-query resamplers derived from it appear in OpenFlamingo, IDEFICS and [Qwen-VL](/paper/2308.12966); the [Q-Former](/methods/q-former) is a related design.',
    'perceiver resampler',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2022,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2204.14198'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'Flamingo: a Visual Language Model for Few-Shot Learning',
    'https://github.com/mlfoundations/open_flamingo/blob/main/open_flamingo/src/helpers.py',
    NULL,
    '[Flamingo: a Visual Language Model for Few-Shot Learning](/paper/2204.14198)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id
FROM methods
WHERE slug = 'perceiver-resampler'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source'
FROM methods
WHERE slug = 'perceiver-resampler'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

